using System.Text.Json;using Npgsql;using UDrive.Api.Common;using UDrive.Api.Models;
namespace UDrive.Api.Services;
public sealed class PaymentService(string connectionString){NpgsqlConnection Open()=>new(connectionString);
public async Task<ServiceResult<BookingPaymentSummaryDto>> BookingSummaryAsync(Guid userId,bool admin,Guid bookingId,CancellationToken ct){await using var cn=Open();await cn.OpenAsync(ct);const string q=@"select b.booking_reference,b.total_amount,b.customer_user_id,coalesce(sum(case when p.status in ('Paid','Verified') then p.amount else 0 end),0),coalesce(sum(p.refund_amount),0) from udrive.bookings b left join udrive.payments p on p.booking_id=b.id where b.id=@b group by b.id";await using var c=new NpgsqlCommand(q,cn);c.Parameters.AddWithValue("b",bookingId);await using var r=await c.ExecuteReaderAsync(ct);if(!await r.ReadAsync(ct))return ServiceResult<BookingPaymentSummaryDto>.Fail(404,"booking_not_found","Booking not found.");var reference=r.GetString(0);var total=r.GetDecimal(1);var customer=r.GetGuid(2);var paid=r.GetDecimal(3);var refunded=r.GetDecimal(4);if(!admin&&customer!=userId)return ServiceResult<BookingPaymentSummaryDto>.Fail(403,"forbidden","You cannot view this booking payment.");await r.DisposeAsync();var payments=await LoadPayments(cn,bookingId,ct);return ServiceResult<BookingPaymentSummaryDto>.Ok(new(bookingId,reference,total,paid,refunded,Math.Max(0,total-paid+refunded),"PKR",payments));}
public async Task<ServiceResult<PaymentRecordDto>> CreateAsync(Guid userId,bool admin,CreateBookingPaymentRequest req,CancellationToken ct){var summary=await BookingSummaryAsync(userId,admin,req.BookingId,ct);if(!summary.Success)return ServiceResult<PaymentRecordDto>.Fail(summary.StatusCode,summary.ErrorCode!,summary.Message);if(req.Amount>summary.Data!.RemainingAmount)return ServiceResult<PaymentRecordDto>.Fail(409,"amount_exceeds_balance","Payment amount exceeds the remaining balance.");var method=NormalizeMethod(req.Method);if(method is null)return ServiceResult<PaymentRecordDto>.Fail(400,"invalid_method","Use Cash, BankTransfer, Card, Easypaisa or JazzCash.");await using var cn=Open();await cn.OpenAsync(ct);await using var tx=await cn.BeginTransactionAsync(ct);var id=Guid.NewGuid();var status=method=="Cash"?"PendingVerification":"Pending";const string sql=@"insert into udrive.payments(id,booking_id,method,payment_type,amount,currency,status,provider,idempotency_key,created_by_user_id,created_at,updated_at) values(@id,@b,@m,@t,@a,'PKR',@s,@p,@k,@u,now(),now()) on conflict(idempotency_key) where idempotency_key is not null do nothing";await Exec(cn,tx,sql,ct,("id",id),("b",req.BookingId),("m",method),("t",req.PaymentType.Trim()),("a",req.Amount),("s",status),("p",method=="Card"?"Gateway":null),("k",req.IdempotencyKey.Trim()),("u",userId));await using var get=new NpgsqlCommand("select id from udrive.payments where idempotency_key=@k",cn,tx);get.Parameters.AddWithValue("k",req.IdempotencyKey.Trim());id=(Guid)(await get.ExecuteScalarAsync(ct))!;await Exec(cn,tx,"insert into udrive.payment_attempts(id,payment_id,attempt_number,status,request_json,created_at) values(gen_random_uuid(),@p,1,@s,cast(@j as jsonb),now()) on conflict do nothing",ct,("p",id),("s",status),("j",JsonSerializer.Serialize(req)));await tx.CommitAsync(ct);var row=(await LoadPayments(cn,req.BookingId,ct)).First(x=>x.Id==id);return ServiceResult<PaymentRecordDto>.Ok(row,"Payment initiated.");}
public async Task<ServiceResult<PaymentRecordDto>> ConfirmAsync(Guid actor,Guid paymentId,ConfirmBookingPaymentRequest req,CancellationToken ct){var allowed=new[]{"Paid","Verified","Failed","Cancelled"};if(!allowed.Contains(req.Status))return ServiceResult<PaymentRecordDto>.Fail(400,"invalid_status","Invalid payment status.");await using var cn=Open();await cn.OpenAsync(ct);await using var tx=await cn.BeginTransactionAsync(ct);const string q=@"update udrive.payments set status=@s,provider_reference=coalesce(@r,provider_reference),failure_reason=@f,paid_at=case when @s in ('Paid','Verified') then now() else paid_at end,reviewed_by_user_id=@u,reviewed_at=now(),updated_at=now() where id=@id returning booking_id";await using var c=new NpgsqlCommand(q,cn,tx);c.Parameters.AddWithValue("s",req.Status);c.Parameters.AddWithValue("r",(object?)req.ProviderReference??DBNull.Value);c.Parameters.AddWithValue("f",(object?)req.FailureReason??DBNull.Value);c.Parameters.AddWithValue("u",actor);c.Parameters.AddWithValue("id",paymentId);var x=await c.ExecuteScalarAsync(ct);if(x is not Guid booking)return ServiceResult<PaymentRecordDto>.Fail(404,"payment_not_found","Payment not found.");var n=await Scalar(cn,tx,"select coalesce(max(attempt_number),0)+1 from udrive.payment_attempts where payment_id=@p",ct,("p",paymentId));await Exec(cn,tx,"insert into udrive.payment_attempts(id,payment_id,attempt_number,status,provider_reference,failure_reason,created_at) values(gen_random_uuid(),@p,@n,@s,@r,@f,now())",ct,("p",paymentId),("n",n),("s",req.Status),("r",req.ProviderReference),("f",req.FailureReason));await tx.CommitAsync(ct);return ServiceResult<PaymentRecordDto>.Ok((await LoadPayments(cn,booking,ct)).First(x=>x.Id==paymentId));}
public async Task<ServiceResult<IReadOnlyList<PayoutAccountDto>>> AccountsAsync(Guid user,CancellationToken ct){var d=await DriverId(user,ct);if(d is null)return ServiceResult<IReadOnlyList<PayoutAccountDto>>.Fail(404,"driver_not_found","Driver profile not found.");await using var cn=Open();await cn.OpenAsync(ct);var list=new List<PayoutAccountDto>();await using var c=new NpgsqlCommand("select id,method,account_title,account_identifier_masked,bank_name,is_default,is_verified from udrive.driver_payout_accounts where driver_profile_id=@d order by is_default desc,created_at desc",cn);c.Parameters.AddWithValue("d",d);await using var r=await c.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))list.Add(new(r.GetGuid(0),r.GetString(1),r.GetString(2),r.GetString(3),r.IsDBNull(4)?null:r.GetString(4),r.GetBoolean(5),r.GetBoolean(6)));return ServiceResult<IReadOnlyList<PayoutAccountDto>>.Ok(list);}
public async Task<ServiceResult<PayoutAccountDto>> SaveAccountAsync(Guid user,SavePayoutAccountRequest req,CancellationToken ct){var d=await DriverId(user,ct);if(d is null)return ServiceResult<PayoutAccountDto>.Fail(404,"driver_not_found","Driver profile not found.");var raw=req.AccountIdentifier.Trim();var masked=raw.Length<=4?new string('*',raw.Length):new string('*',raw.Length-4)+raw[^4..];await using var cn=Open();await cn.OpenAsync(ct);await using var tx=await cn.BeginTransactionAsync(ct);if(req.IsDefault)await Exec(cn,tx,"update udrive.driver_payout_accounts set is_default=false,updated_at=now() where driver_profile_id=@d",ct,("d",d));var id=Guid.NewGuid();await Exec(cn,tx,@"insert into udrive.driver_payout_accounts(id,driver_profile_id,method,account_title,account_identifier_hash,account_identifier_masked,bank_name,is_default,created_at,updated_at) values(@id,@d,@m,@t,@e,@x,@b,@def,now(),now())",ct,("id",id),("d",d),("m",req.Method.Trim()),("t",req.AccountTitle.Trim()),("e",Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(System.Text.Encoding.UTF8.GetBytes(raw)))),("x",masked),("b",req.BankName),("def",req.IsDefault));await tx.CommitAsync(ct);return ServiceResult<PayoutAccountDto>.Ok(new(id,req.Method.Trim(),req.AccountTitle.Trim(),masked,req.BankName,req.IsDefault,false));}
async Task<IReadOnlyList<PaymentRecordDto>> LoadPayments(NpgsqlConnection cn,Guid booking,CancellationToken ct){var list=new List<PaymentRecordDto>();await using var c=new NpgsqlCommand("select id,method,payment_type,amount,currency,status,provider,provider_reference,failure_reason,created_at,paid_at from udrive.payments where booking_id=@b order by created_at desc",cn);c.Parameters.AddWithValue("b",booking);await using var r=await c.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))list.Add(new(r.GetGuid(0),r.GetString(1),r.GetString(2),r.GetDecimal(3),r.GetString(4),r.GetString(5),r.IsDBNull(6)?null:r.GetString(6),r.IsDBNull(7)?null:r.GetString(7),r.IsDBNull(8)?null:r.GetString(8),r.GetFieldValue<DateTimeOffset>(9),r.IsDBNull(10)?null:r.GetFieldValue<DateTimeOffset>(10)));return list;}
async Task<Guid?> DriverId(Guid u,CancellationToken ct){await using var cn=Open();await cn.OpenAsync(ct);await using var c=new NpgsqlCommand("select id from udrive.driver_profiles where user_id=@u",cn);c.Parameters.AddWithValue("u",u);return await c.ExecuteScalarAsync(ct) is Guid g?g:null;}
static string? NormalizeMethod(string x){var v=x.Trim().ToLowerInvariant();return v switch{"cash"=>"Cash","banktransfer" or "bank transfer"=>"BankTransfer","card"=>"Card","easypaisa"=>"Easypaisa","jazzcash"=>"JazzCash",_=>null};}
static async Task Exec(NpgsqlConnection cn,NpgsqlTransaction tx,string sql,CancellationToken ct,params(string,object?)[] p){await using var c=new NpgsqlCommand(sql,cn,tx);foreach(var x in p)c.Parameters.AddWithValue(x.Item1,x.Item2??DBNull.Value);await c.ExecuteNonQueryAsync(ct);}static async Task<int> Scalar(NpgsqlConnection cn,NpgsqlTransaction tx,string sql,CancellationToken ct,params(string,object?)[] p){await using var c=new NpgsqlCommand(sql,cn,tx);foreach(var x in p)c.Parameters.AddWithValue(x.Item1,x.Item2??DBNull.Value);return Convert.ToInt32(await c.ExecuteScalarAsync(ct));}}
